import json
from pathlib import Path
p=Path(__file__).parent
subjects=[]
def add(id,name,levels,category,short='',description='',suits=[],experience='',skills=[],considerations='',source=''):
 subjects.append(dict(subject_id=id,subject_name=name,levels=levels,category=category,short_description=short,full_description=description,suitable_for=suits,learning_experience=experience,skills=skills,considerations=considerations,source=source,review_status='ready' if description else 'requires_completion',active=True))
add('geo','Geography',['G2','G3'],'Humanities','Explore how people and environments shape one another.','Geography explores physical and human environments and the connections between them. You will investigate how people affect environmental sustainability, and how environmental changes affect people. Using real-world examples from Singapore and beyond, you will analyse geographical information and consider different views and possible responses to sustainability challenges.',['Are curious about people and the environment','Enjoy understanding connections between places','Like using data to investigate real-world questions'],'Investigate geographical questions, analyse data and discuss responses to environmental challenges.',['Inquiry','Data analysis','Holistic thinking','Reasoning'],'You will explain geographical processes, interpret evidence and connect ideas across different contexts.','Supplied G2 booklet, PDF p.4; G3 booklet, PDF pp.4–5, 7; descriptors only')
add('hist','History',['G2','G3'],'Humanities','Use evidence from the past to understand the world today.','History helps you understand international relations and how past forces, events and developments have shaped today’s world. You will examine how the past has been interpreted for different purposes, ask questions and investigate sources in their historical context. You will learn to form judgements supported by evidence and reflect on different perspectives.',['Have an interest in current affairs','Are curious about how people and politics shape the world','Enjoy independent research and learning'],'Examine historical sources, discuss interpretations and write evidence-based responses.',['Critical thinking','Source analysis','Research','Communication'],'You will read sources carefully and develop written explanations and arguments.','Supplied G2 booklet, PDF p.5; G3 booklet, PDF p.5; descriptors only')
add('lit','Literature in English',['G2','G3'],'Humanities','Discover how writers use language to create meaning.','Literature explores how writers use language, form and structure to create meaning. You will enter imagined worlds and examine themes connected to human experience, such as identity, family and discrimination. Close reading helps you develop your own responses and make connections between texts, your life and the wider world.',['Enjoy reading and writing','Appreciate creative uses of language','Are curious about human nature','Enjoy considering different ways of seeing the world'],'Read texts closely, analyse writers’ choices and craft thoughtful written responses.',['Close reading','Interpretation','Written expression','Perspective-taking'],'Reading and extended writing are central. You will support interpretations with details from texts.','Supplied G3 booklet, PDF p.6; general descriptor, G2 details require staff review')
add('am','Additional Mathematics',['G3'],'Mathematics','Explore algebra, geometry, trigonometry and change.','Additional Mathematics develops mathematical ideas through algebra, geometry and trigonometry, and calculus. Algebra helps you represent patterns and relationships, while geometry builds spatial understanding. Trigonometry supports the study of periodic patterns, and calculus explores change. You will develop mathematical reasoning and learn to use abstract ideas to solve problems.',['Enjoy working with algebra and geometry','Like abstract patterns and logical problems','Are willing to practise regularly'],'Work through mathematical problems, connect representations and develop reasoning through regular practice.',['Algebraic reasoning','Spatial thinking','Problem solving','Perseverance'],'A secure foundation in algebra and geometry is helpful. Allow time for regular practice.','Supplied G3 booklet, PDF p.8; descriptor only; numerical prerequisites excluded')
add('chem','Chemistry',['G3'],'Science','Investigate matter, its structure and how it changes.','Chemistry investigates what matter is made of, how it is structured, and how substances transform and interact. You will connect the properties of materials with ideas about their structure at a very small scale. Scientific enquiry helps you make sense of materials and changes that occur in everyday life.',['Are curious about everyday materials','Enjoy finding explanations for changes','Like connecting observations with scientific ideas'],'Use scientific evidence and explanations to explore materials and their interactions.',['Scientific reasoning','Evidence analysis','Communication'],'You will connect observations with abstract models and explain scientific relationships.','Supplied G3 booklet, PDF p.9; descriptor only')
add('bio','Biology',['G3'],'Science','Explore living organisms and their interactions.','Biology is the study of life. It explores the characteristics and behaviour of organisms, how living things are classified, and their interactions with one another and the environment. You will connect ideas across different scales and develop scientific explanations for biological phenomena.',['Are curious about living things','Enjoy explaining processes step by step','Like exploring connections in the natural world'],'Develop explanations for biological processes and interpret scientific information.',['Scientific reasoning','Explanation','Making connections'],'You will organise explanations clearly and describe complex processes step by step.','Supplied G3 booklet, PDF pp.9–10; descriptor only')
add('phy','Physics',['G3'],'Science','Explore matter, energy and the principles of nature.','Physics explores the underlying principles of the natural world. It investigates matter, energy and their interactions, and helps explain systems using fundamental ideas. Mathematics provides an important language for expressing these principles. You will learn to use scientific reasoning and mathematical relationships to make sense of physical phenomena.',['Are curious about how the physical world works','Enjoy applying mathematics','Like reasoning from underlying principles'],'Use mathematical relationships and scientific explanations to investigate physical phenomena.',['Mathematical reasoning','Problem solving','Scientific thinking'],'You will use mathematics to support explanations and solve problems.','Supplied G3 booklet, PDF pp.9–10; descriptor only')
for id,name,branch in [('cb','Science (Chemistry, Biology)','Biology'),('cp','Science (Chemistry, Physics)','Physics')]:
 add(id,name,['G2','G3'],'Science','Study Chemistry together with '+branch+'.','This subject brings together Chemistry and '+branch+'. Chemistry explores matter, its structure and how substances change. '+('Biology explores living organisms and their interactions with one another and the environment.' if branch=='Biology' else 'Physics explores matter, energy and their interactions, using mathematics to express scientific relationships.')+' You will develop scientific reasoning and learn to communicate explanations across both components.',['Enjoy understanding scientific ideas','Are interested in both science components','Like connecting ideas to everyday life'],'Study both components, interpret scientific information and develop clear explanations.',['Scientific reasoning','Evidence analysis','Communication'],'Plan time for both components. '+('Practise explaining biological processes step by step.' if branch=='Biology' else 'Mathematics supports your learning in Physics.'),'Supplied G2 booklet, PDF p.6; G3 booklet, PDF pp.9–10; descriptors only')
add('art','Art',['G2'],'Creative & applied','Express ideas through visual exploration and art-making.','Art develops your confidence to express ideas visually and discover your personal voice. You will explore materials and techniques, make artworks and respond to the work of artists. Through observation, experimentation and reflection, you will develop visual literacy and an appreciation of different social and cultural perspectives.',['Enjoy drawing or other forms of art-making','Like exploring the creative process','Enjoy expressing ideas visually'],'Explore media and techniques, create artworks and analyse and interpret visual work.',['Creativity','Observation','Visual communication','Reflection'],'Make time to experiment, develop your ideas and reflect on your artistic choices.','Supplied G2 booklet, PDF pp.8–9; descriptors only; school-specific programmes excluded')
add('dt','Design & Technology',['G2','G3'],'Creative & applied','Turn researched ideas into functional design solutions.','Design & Technology develops your designing and making skills. You will investigate needs, research possible solutions and use sketches and mock-ups to develop ideas. Applying knowledge of systems, control and materials, you will plan and make a working product, considering its appearance, function and safety.',['Enjoy sketching and creating solutions','Like turning ideas into working products','Are willing to research, test and improve ideas'],'Research a design opportunity, develop annotated sketches and mock-ups, plan production and make a prototype.',['Design thinking','Research','Planning','Evaluation'],'Design work involves sustained development, documentation and careful use of materials and equipment.','Supplied G2 booklet, PDF p.10; general descriptor adapted; G3 detail requires review')
add('nfs','Nutrition and Food Science',['G2'],'Creative & applied','Apply food science to healthy and sustainable choices.','Nutrition and Food Science explores nutrition and health, food literacy and the principles of food science. You will connect these ideas with everyday situations through practical work and coursework. You will consider healthy eating and sustainable food choices, and apply culinary science creatively when planning, preparing and evaluating food.',['Care about nutrition and health','Are curious about food safety and sustainability','Enjoy applying science in food preparation'],'Research tasks, plan dishes, record and interpret experimental results, prepare food and evaluate outcomes.',['Research','Decision making','Practical application','Evaluation'],'Learning includes practical preparation, planning, recording results and evaluating food products.','Supplied G2 booklet, PDF p.11; descriptors only')
add('poa','Principles of Accounts',['G2','G3'],'Business','Use accounting information to understand business decisions.','Principles of Accounts introduces fundamental accounting concepts and the reasons behind accounting procedures. You will learn the double-entry bookkeeping method and develop skills in preparing, analysing and interpreting financial statements. The subject shows how accounting information supports business monitoring and decision making, while developing accuracy, logical thinking and an appreciation of professional ethics.',['Are interested in businesses and the decisions they make','Enjoy working with calculations and numerical information','Like organised and logical work'],'Prepare and interpret accounting information and consider its implications for business decisions.',['Numeracy','Analysis','Logical thinking','Accuracy'],'You will work carefully with numbers and learn to explain the reasoning behind accounting information.','Supplied G3 booklet, PDF p.14; G2 booklet descriptor; no entry criteria imported')
for id,name,levels,cat in [('el','English Language',['G1','G2','G3'],'Core'),('mt','Mother Tongue Language',['G1','G2','G3'],'Core'),('math','Mathematics',['G1','G2','G3'],'Core'),('ss','Social Studies',['G2','G3'],'Core'),('sci','Science',['G1'],'Core'),('hum','Humanities (non-examinable)',['G1'],'Core'),('econ','Economics',['G3'],'Business'),('comp','Computing',['G1','G3'],'Computing'),('ebs','Elements of Business Skills',['G1'],'Business'),('music','Music',['G3'],'Creative & applied')]: add(id,name,levels,cat)
base=['el','mt','math']
def g(id,label,options,rank=False):return dict(id=id,label=label,options=options,min_select=1,max_select=1,rank_required=False)
combos=[dict(combination_id='g3pure',profile='G3',combination_name='Pure Science',description='Chemistry + Biology or Physics, with Additional Mathematics.',compulsory=base+['ss','chem','am'],groups=[g('humanities','Elective Humanities',['geo','hist','lit'],True),g('science','Second Pure Science',['bio','phy'])],optional=[],closed_optional=['comp','music'],active=True),dict(combination_id='g3combined',profile='G3',combination_name='Combined Science',description='Two science components in one subject, with an additional elective.',compulsory=base+['ss'],groups=[g('humanities','Elective Humanities',['geo','hist','lit'],True),g('science','Science combination',['cb','cp']),g('elective','Other subject',['geo','hist','lit','poa','econ','dt'],True)],optional=['am'],closed_optional=['comp','music'],active=True),dict(combination_id='g2',profile='G2',combination_name='G2 subject combination',description='Combined Science, Elective Humanities and an applied or creative subject.',compulsory=base+['ss'],groups=[g('science','Science combination',['cp','cb']),g('humanities','Elective Humanities',['geo','hist','lit'],True),g('elective','Other subject',['art','dt','nfs','poa'],True)],optional=[],closed_optional=[],active=True),dict(combination_id='g1',profile='G1',combination_name='G1 subject combination',description='Core subjects with Computing or Elements of Business Skills.',compulsory=base+['sci','hum'],groups=[g('elective','Other subject',['comp','ebs'],True)],optional=[],closed_optional=[],active=True)]
for combo in combos:
 combo['optional_groups']=[dict(id='eighth',label='Optional 8th subject',options=['comp','music'],min_select=0,max_select=1)] if combo['profile']=='G3' else []
 if combo['profile']=='G3': combo['closed_optional']=[]
elig=[]
def e(subject,level,text):elig.append(dict(subject_id=subject,subject_level=level,eligibility_text=text,active=True))
e('g3pure','G3','Obtain a good pass in Science; obtain a pass in Mathematics; recommendation by subject teachers.')
for s,t in [('am','Mathematics'),('lit','Literature'),('geo','Geography'),('hist','History'),('econ','English Language'),('poa','Mathematics'),('dt','Design & Technology')]: e(s,'G3','Obtain a good pass in '+t+'.')
e('cb','G2','Strong aptitude in Science; strong aptitude in English.')
for s,t in [('art','Art'),('dt','Design & Technology'),('nfs','Nutrition & Food Science'),('poa','Mathematics')]: e(s,'G2','Obtain a good pass in '+t+'.')
e('comp','G1','Strong aptitude in Mathematics.');e('ebs','G1','Strong aptitude in English Language.')
data=dict(version=1,updated='26 October 2026',subjects=subjects,combinations=combos,eligibility=elig,sources=dict(combinations='Westwood 2026 Final Subject Option Briefing, 20 October 2026, PDF pp.4–10',pathways='A Guide to the 2028 PSE, slides 6, 11–18, 22, 25, 27 and 29; checked against the MOE PSE pages',descriptors='Supplied subject information booklets: subject descriptions only.'))
(p/'dist/data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
